window.MODULE_QCM_BANKS.grammar = {
  title: "លំហាត់ QCM ទី ៥ • វេយ្យាករណ៍ សព្វនាម ពាក្យសួរ WH និងកាលទាំង ១២ (២០ សំណួរ)",
  subtitle: "វាស់ស្ទង់ការប្រើប្រាស់កាលវេយ្យាករណ៍ សព្វនាម កិរិយាសព្ទជំនួយ ប្រយោគលក្ខខណ្ឌ និងធ្នាក់",
  questions: [
    { q: "ជ្រើសរើសកិរិយាសព្ទត្រឹមត្រូវ (Present Simple)៖ 'Teacher Sokha _______ her lesson plans every evening.'", options: ["prepare", "prepares", "preparing", "prepared"], correct: 1, exp: "ក្នុង Present Simple (every evening) ប្រធានឯកវចនៈបុរសទី៣ (Teacher Sokha = She) កិរិយាសព្ទត្រូវថែម -s -> prepares។" },
    { q: "បំពេញប្រយោគសំណួរក្នុង Present Simple៖ '_______ the students read in the library on Fridays?'", options: ["Do", "Does", "Are", "Have"], correct: 0, exp: "ប្រធានពហុវចនៈ 'the students' (They) និងមានកិរិយាសព្ទដើម 'read' ត្រូវប្រើជំនួយការ 'Do'។" },
    { q: "បំពេញប្រយោគ Present Continuous៖ 'Listen! The children _______ an English song in the classroom.'", options: ["sing", "sings", "are singing", "sang"], correct: 2, exp: "ពាក្យ 'Listen!' បង្ហាញពីសកម្មភាពកំពុងកើតឡើងនៅពេលនិយាយ (am/is/are + V-ing) -> are singing។" },
    { q: "បំពេញប្រយោគ Past Simple៖ 'The school principal _______ our classroom yesterday morning.'", options: ["visit", "visits", "visited", "visiting"], correct: 2, exp: "មានពាក្យ 'yesterday morning' ជាអតីតកាលធម្មតា (Past Simple) ដូច្នេះប្រើ V2 -> visited។" },
    { q: "ជ្រើសរើសទម្រង់បដិសេធត្រឹមត្រូវក្នុងអតីតកាល (Past Simple)៖ 'Dara _______ absent from class last week.'", options: ["did not", "was not", "were not", "does not"], correct: 1, exp: "'absent' ជាគុណនាម (មិនមែនកិរិយាសព្ទសកម្មភាពទេ) ដូច្នេះត្រូវប្រើ Verb to be ក្នុងអតីតកាលសម្រាប់ Dara (He) គឺ 'was not' (wasn't)។" },
    { q: "បំពេញប្រយោគ Past Continuous៖ 'The students _______ quietly when the bell rang.'", options: ["read", "are reading", "were reading", "have read"], correct: 2, exp: "សកម្មភាពកំពុងដំណើរការក្នុងអតីតកាល (Past Continuous: was/were + V-ing) ពេលមានសកម្មភាពមួយទៀតកាត់ (when the bell rang) -> were reading។" },
    { q: "ជ្រើសរើសអនាគតកាលសម្រាប់ផែនការគ្រោងទុក៖ 'We _______ organize a reading competition next month.'", options: ["are going to", "will be", "going to", "were going"], correct: 0, exp: "សម្រាប់ផែនការដែលបានគ្រោងទុករួចហើយ យើងប្រើ 'am/is/are + going to + V1' -> are going to។" },
    { q: "បំពេញប្រយោគ Present Perfect៖ 'She _______ Grade 5 at this school for eight years.'", options: ["teaches", "taught", "has taught", "is teaching"], correct: 2, exp: "មានឃ្លាប្រាប់រយៈពេល 'for eight years' (រយៈពេល ៨ ឆ្នាំមកដល់បច្ចុប្បន្ន) ត្រូវប្រើ Present Perfect (have/has + V3) -> has taught។" },
    { q: "តើពាក្យ 'for' និង 'since' ខុសគ្នាដូចម្តេចក្នុង Present Perfect?", options: ["for + រយៈពេល (for 5 years) រីឯ since + ចំណុចចាប់ផ្តើមនៃពេលវេលា (since 2020)", "ប្រើដូចគ្នាគ្រប់ករណី", "for ប្រើសម្រាប់អតីតកាល រីឯ since ប្រើសម្រាប់អនាគតកាល", "since + ចំនួនម៉ោង រីឯ for + ឈ្មោះថ្ងៃ"], correct: 0, exp: "'for' បូកនឹងរយៈពេលសរុប (for ten years) ចំណែក 'since' បូកនឹងចំណុចចាប់ផ្តើមជាក់លាក់ (since 2018 / since Monday)។" },
    { q: "ជ្រើសរើសទម្រង់ត្រឹមត្រូវក្រោយ Modal Verb៖ 'Students must _______ clean uniforms to school.'", options: ["wears", "wearing", "to wear", "wear"], correct: 3, exp: "ក្រោយ Modal Verbs (can, could, should, must, may) កិរិយាសព្ទត្រូវតែជាទម្រង់ដើម (V1 គ្មាន to និងគ្មាន -s) -> wear។" },
    { q: "បំពេញប្រយោគប្រៀបធៀប (Comparative)៖ 'Bora's handwriting is _______ than it was last month.'", options: ["neat", "neater", "neatest", "more neat"], correct: 1, exp: "'neat' ជាគុណនាមខ្លី ១ ព្យាង្គ និងមានពាក្យ 'than' ដូច្នេះត្រូវថែម -er -> neater than។" },
    { q: "បំពេញប្រយោគប្រៀបធៀបផុតលេខ (Superlative)៖ 'Reading is one of _______ skills in primary school.'", options: ["important", "more important", "the most important", "most important"], correct: 2, exp: "គុណនាមវែងក្នុងកម្រិតផុតលេខ (Superlative) ត្រូវប្រើ 'the most + Adjective' -> the most important។" },
    { q: "បំពេញប្រយោគលក្ខខណ្ឌទី ១ (First Conditional)៖ 'If a student _______ with fractions, the teacher will give extra support.'", options: ["struggle", "struggles", "will struggle", "struggled"], correct: 1, exp: "ក្នុងឃ្លា If នៃ First Conditional ត្រូវប្រើ Present Simple (ហាមប្រើ will)។ ប្រធាន 'a student' (ឯកវចនៈ) -> struggles។" },
    { q: "បំពេញប្រយោគកម្មវាចក (Passive Voice)៖ 'Monthly test scores _______ in the digital system.'", options: ["record", "are recorded", "is recorded", "recording"], correct: 1, exp: "ប្រធាន 'Monthly test scores' (ពហុវចនៈ) ទទួលរងអំពើ ត្រូវប្រើ Passive Voice (are + V3) -> are recorded។" },
    { q: "ជ្រើសរើសធ្នាក់ប្រាប់ពេលវេលា (Prepositions of Time)៖ 'The new academic year starts ___ November ___ 7:00 AM.'", options: ["on / at", "in / at", "at / in", "in / on"], correct: 1, exp: "ប្រើ 'in' សម្រាប់ខែ/ឆ្នាំ (in November) និងប្រើ 'at' សម្រាប់ម៉ោងជាក់លាក់ (at 7:00 AM)។" },
    { q: "ជ្រើសរើសសព្វនាមឆ្លុះ (Reflexive Pronoun)៖ 'I prepare my lesson plan by _______.'", options: ["me", "mine", "myself", "himself"], correct: 2, exp: "ប្រធាន 'I' ត្រូវប្រើសព្វនាមឆ្លុះ 'myself' (by myself = ដោយខ្លួនខ្ញុំផ្ទាល់)។" },
    { q: "ជ្រើសរើសគុណនាមកម្មសិទ្ធិ (Possessive Adjective)៖ 'She helps _______ students with great care.'", options: ["she", "her", "hers", "herself"], correct: 1, exp: "មុននាម 'students' ត្រូវប្រើគុណនាមកម្មសិទ្ធិរបស់ She គឺ 'her'។" },
    { q: "ជ្រើសរើសពាក្យសួរ (WH-Question) សម្រាប់សួររកម្ចាស់កម្មសិទ្ធិ៖ '_______ notebook is this on the teacher's desk?'", options: ["Who", "Whose", "Which", "Whom"], correct: 1, exp: "'Whose' (របស់នរណា) ប្រើនៅមុននាមដើម្បីសួររកម្ចាស់កម្មសិទ្ធិ (Whose notebook is this?)។" },
    { q: "ជ្រើសរើសពាក្យសួររកភាពញឹកញាប់៖ '_______ does your school hold PLC meetings?' — 'Once a week.'", options: ["How long", "How often", "How many", "How much"], correct: 1, exp: "'How often' (ញឹកញាប់ប៉ុណ្ណា) ប្រើសម្រាប់សួររកភាពញឹកញាប់នៃសកម្មភាព។" },
    { q: "ជ្រើសរើសឈ្នាប់ភ្ជាប់សេចក្តី (Connector) ត្រឹមត្រូវ៖ '_______ the math problem was difficult, the students worked it out.'", options: ["Because", "Although", "Therefore", "However"], correct: 1, exp: "'Although' (ទោះបីជា...ក៏ដោយ) ប្រើភ្ជាប់ឃ្លាពីរដែលមានន័យផ្ទុយគ្នា។" }
  ]
};

